17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
30	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
31	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
32	import org.springframework.samples.petclinic.mapper.OwnerMapper;
33	import org.springframework.samples.petclinic.mapper.PetMapper;
34	import org.springframework.samples.petclinic.mapper.VisitMapper;
35	import org.springframework.samples.petclinic.model.Owner;
36	import org.springframework.samples.petclinic.model.Pet;
37	import org.springframework.samples.petclinic.model.Visit;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.security.access.prepost.PreAuthorize;
47	import org.springframework.util.StringUtils;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
66	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
67	     * address shape rather than full RFC 5322 conformance.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    /**
116	     * Rejects an owner payload that is missing or blank in any required field. The response body's
117	     * {@code errors} array lists the name of each offending field.
118	     *
119	     * @param ownerFieldsDto the owner payload to validate
120	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
121	     */
122	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
123	        List<String> missingFields = new ArrayList<>();
124	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
125	            missingFields.add("firstName");
126	        }
127	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
128	            missingFields.add("lastName");
129	        }
130	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
131	            missingFields.add("address");
132	        }
133	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
134	            missingFields.add("city");
135	        }
136	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
137	            missingFields.add("telephone");
138	        }
139	        if (!missingFields.isEmpty()) {
140	            throw new RequiredFieldsMissingException(missingFields);
141	        }
142	    }
143	
144	    /**
145	     * Normalizes a telephone number by removing every non-digit character and requires the
146	     * result to be exactly 10 digits.
147	     *
148	     * @param telephone the raw telephone value from the request
149	     * @return the 10-digit, digits-only telephone
150	     * @throws InvalidFieldsException if the stripped value is not exactly 10 digits
151	     */
152	    private String normalizeTelephone(String telephone) {
153	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
154	        if (digits.length() != 10) {
155	            throw new InvalidFieldsException(List.of("telephone"));
156	        }
157	        return digits;
158	    }
159	
160	    /**
161	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
162	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
163	     * be a syntactically valid address; the accepted value is returned lower-cased.
164	     *
165	     * @param email the raw email value from the request, may be {@code null}
166	     * @return the lower-cased email, or {@code null} when none was supplied
167	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
168	     */
169	    private String normalizeEmail(String email) {
170	        if (email == null || email.isBlank()) {
171	            return null;
172	        }
173	        String trimmed = email.trim();
174	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
175	            throw new InvalidFieldsException(List.of("email"));
176	        }
177	        return trimmed.toLowerCase(Locale.ROOT);
178	    }
179	
180	    /**
181	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
182	     * owners' telephones are normalized the same way before comparison so differently-formatted
183	     * values representing the same number are treated as duplicates.
184	     *
185	     * @param telephone the normalized (digits-only) telephone of the owner being created
186	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
187	     */
188	    private void requireUniqueTelephone(String telephone) {
189	        boolean taken = this.clinicService.findAllOwners().stream()
190	            .map(Owner::getTelephone)
191	            .filter(existing -> existing != null)
192	            .map(existing -> existing.replaceAll("\\D", ""))
193	            .anyMatch(telephone::equals);
194	        if (taken) {
195	            throw new DuplicateOwnerTelephoneException(telephone);
196	        }
197	    }
198	
199	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
200	    @Override
201	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
202	        validateRequiredFields(ownerFieldsDto);
203	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
204	        requireUniqueTelephone(telephone);
205	        String email = normalizeEmail(ownerFieldsDto.getEmail());
206	        HttpHeaders headers = new HttpHeaders();
207	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
208	        owner.setTelephone(telephone);
209	        owner.setEmail(email);
210	        if (owner.getRegistrationDate() == null) {
211	            owner.setRegistrationDate(LocalDate.now());
212	        }
213	        this.clinicService.saveOwner(owner);
214	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
215	        headers.setLocation(UriComponentsBuilder.newInstance()
216	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
217	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
223	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
224	        if (currentOwner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        currentOwner.setAddress(ownerFieldsDto.getAddress());
228	        currentOwner.setCity(ownerFieldsDto.getCity());
229	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
230	        currentOwner.setLastName(ownerFieldsDto.getLastName());
231	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
232	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
233	        this.clinicService.saveOwner(currentOwner);
234	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
235	    }
236	
237	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
238	    @Transactional
239	    @Override
240	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
241	        Owner owner = this.clinicService.findOwnerById(ownerId);
242	        if (owner == null) {
243	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
244	        }
245	        this.clinicService.deleteOwner(owner);
246	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
252	        Owner owner = this.clinicService.findOwnerById(ownerId);
253	        if (owner == null) {
254	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	        }
256	        HttpHeaders headers = new HttpHeaders();
257	        Pet pet = petMapper.toPet(petFieldsDto);
258	        owner.setId(ownerId);
259	        pet.setOwner(owner);
260	        pet.getType().setName(null);
261	        this.clinicService.savePet(pet);
262	        PetDto petDto = petMapper.toPetDto(pet);
263	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
264	            .buildAndExpand(pet.getId()).toUri());
265	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
266	    }
267	
268	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
269	    @Override
270	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
271	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
272	        if (currentOwner != null) {
273	            Pet currentPet = this.clinicService.findPetById(petId);
274	            if (currentPet != null) {
275	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
276	                currentPet.setName(petFieldsDto.getName());
277	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
278	                this.clinicService.savePet(currentPet);
279	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
280	            }
281	        }
282	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
288	        HttpHeaders headers = new HttpHeaders();
289	        Visit visit = visitMapper.toVisit(visitFieldsDto);
290	        Pet pet = new Pet();
291	        pet.setId(petId);
292	        visit.setPet(pet);
293	        this.clinicService.saveVisit(visit);
294	        VisitDto visitDto = visitMapper.toVisitDto(visit);
295	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
296	            .buildAndExpand(visit.getId()).toUri());
297	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
298	    }
299	
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
304	        Owner owner = this.clinicService.findOwnerById(ownerId);
305	        if (owner != null) {
306	            Pet pet = owner.getPet(petId);
307	            if (pet != null) {
308	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
309	            }
310	        }
311	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
312	    }
313	}
